from langchain_openai import ChatOpenAI
from langchain_ollama import ChatOllama

def create_llm_connector(connector_config: dict):
    provider = connector_config.get("provider", "openai")
    params = connector_config.get("params", {})

    if provider == "openai":
        return ChatOpenAI(**params)
    elif provider == "ollama":
        return ChatOllama(**params)
    else:
        raise ValueError(f"Unsupported provider: {provider}. Only openai and ollama are supported.")
